#!/usr/bin/env node
// Fail when the committed route tree is not what a build produces.
//
// `src/routeTree.gen.ts` is generated by the TanStack router plugin on every
// build and dev start. Nothing had ever checked that the copy in git matched,
// so it drifted: measured on 2026-09-18 the committed file differed from a
// fresh build by 86 lines — the same 4,317 lines in a different order, with
// `Announcements` and `ApiPublicClonesAnnouncements` transposed.
//
// That drift is COSMETIC, and this gate is honest about it: the line multisets
// were identical, so nothing resolved differently and no route was missing.
// What it cost was legibility — every unrelated branch carried 86 lines of
// churn it did not cause, which is how a reviewer stops reading a generated
// file at all and a real change hides in the noise.
//
// WHY THIS ASSERTS AGAINST A BUILD RATHER THAN GENERATING ITS OWN TREE.
// `@tanstack/router-generator` exports `Generator` and `getConfig`, and
// calling them directly is far cheaper than a build. It was tried and
// measured: driven from its own config the generator emitted a tree differing
// from the build's by 406 lines, because the real config is assembled by
// `tanstackStart` and the Lovable vite preset rather than by the defaults. A
// gate that reimplements the build's configuration is a gate that fails for
// reasons the build does not care about — worse than no gate, because people
// learn to ignore it. So this asserts the EFFECT of the real build, which
// cannot disagree with the build by construction.
//
// It therefore means something only AFTER a build has run. CI orders it
// immediately after `npm run build`, and `routeTreeGate.test.ts` pins that
// ordering — a gate placed before the build would pass on a stale tree and
// say nothing, which is the failure it exists to prevent.
//
// Locally:  npm run build && npm run check:route-tree
import { execFileSync } from "node:child_process";
import { existsSync } from "node:fs";

const FILE = "src/routeTree.gen.ts";

if (!existsSync(FILE)) {
  console.error(`check-route-tree: ${FILE} does not exist.`);
  process.exit(1);
}

const git = (args) => execFileSync("git", args, { encoding: "utf8" });

// Is this a git checkout at all? A tarball or a vendored copy is not a
// failure of the route tree — say so rather than reporting drift.
try {
  git(["rev-parse", "--is-inside-work-tree"]);
} catch {
  console.log("check-route-tree: not a git checkout — nothing to compare against.");
  process.exit(0);
}

// Compare the working tree against HEAD, not against the index: a developer
// who regenerated and staged the file has still not committed it, and CI
// checks out clean so the two are the same there anyway.
let diff = "";
try {
  diff = git(["diff", "HEAD", "--", FILE]);
} catch (error) {
  console.error(`check-route-tree: could not diff ${FILE}: ${error.message}`);
  process.exit(1);
}

if (!diff.trim()) {
  console.log(`check-route-tree: ${FILE} is current.`);
  process.exit(0);
}

const changed = diff.split("\n").filter((l) => /^[+-][^+-]/.test(l)).length;
console.error(
  [
    "",
    `check-route-tree: ${FILE} is not what this build produced.`,
    "",
    `  ${changed} line(s) differ between the committed route tree and the one`,
    "  the build just generated. The committed copy is stale.",
    "",
    "  Fix: commit the regenerated file.",
    "",
    "      npm run build && git add src/routeTree.gen.ts",
    "",
    "  Do not hand-edit it. If this fires on a branch that changed no route,",
    "  the file was already stale on the base branch — regenerate and commit",
    "  it there rather than carrying the churn into every future diff.",
    "",
  ].join("\n"),
);
process.exit(1);
